/* Pedagogical AI, image OCR, voice input and offline quick reference. */
let buddyTurns=[];
let activeRecognition=null,currentStudyLesson=null,currentStudySignature='';
function lessonPool(){
 const base=subject==='Toán'?mathLessonsByGrade[grade]:(lessons[level][subject]||lessons[level]['Toán']);
 const rows=subject==='Toán'?(mathBanksByGrade[grade]||[]):((banks[level]&&banks[level][subject])||[]);
 const extras=rows.map((row,i)=>({question:row[0]+' '+row[1].map((x,n)=>`${String.fromCharCode(65+n)}. ${x}`).join(' · '),steps:[`Đọc kỹ đề và xác định kiến thức cần dùng. Em hãy loại trước một lựa chọn chắc chắn chưa đúng.`,`So sánh các lựa chọn còn lại bằng cách thực hiện một phép tính hoặc tìm từ khóa quan trọng. Em chọn phương án nào?`,row[3]],id:`${grade}-${subject}-${i}`}));
 return [{...base,id:`${grade}-${subject}-sample`},...extras];
}
function chooseStudyLesson(force=false){const signature=`${grade}-${subject}`;const pool=lessonPool();if(!force&&currentStudyLesson&&currentStudySignature===signature)return currentStudyLesson;const previous=currentStudyLesson?.id;const choices=pool.filter(x=>x.id!==previous);currentStudyLesson=choices[Math.floor(Math.random()*choices.length)]||pool[0];currentStudySignature=signature;step=0;return currentStudyLesson}
const offlineReference={version:1,formulas:[
 {grade:'6–7',title:'Tỉ lệ thức',value:'a / b = c / d  ⇒  a × d = b × c'},
 {grade:'7–9',title:'Pythagore',value:'Trong tam giác vuông: a² + b² = c²'},
 {grade:'8–9',title:'Hằng đẳng thức',value:'(a + b)² = a² + 2ab + b²'},
 {grade:'8–9',title:'Phương trình bậc nhất',value:'ax + b = 0  ⇒  x = −b/a (a ≠ 0)'},
 {grade:'10–12',title:'Phương trình bậc hai',value:'Δ = b² − 4ac; x = (−b ± √Δ) / 2a'},
 {grade:'10–12',title:'Đạo hàm lũy thừa',value:"(xⁿ)' = n·xⁿ⁻¹"}
],examples:[
 '2x + 5 = 17: bước đầu hãy chuyển 5 sang vế phải.',
 '(x − 2)/3 + (x + 1)/2 = 4: bước đầu hãy tìm BCNN của 3 và 2.',
 'Tam giác vuông có hai cạnh góc vuông: bắt đầu bằng định lý Pythagore.'
]};
try{localStorage.setItem('buddy-offline-reference-v1',JSON.stringify(offlineReference))}catch{}
function renderOfflineReference(){const rows=offlineReference.formulas.filter(x=>grade<=9?!x.grade.startsWith('10'):x.grade.startsWith('10'));return `<details class="offline-reference"><summary>⌁ Công thức & bài mẫu dùng khi mất mạng</summary><div class="offline-reference-grid">${rows.map(x=>`<article><small>${x.grade}</small><b>${x.title}</b><code>${x.value}</code></article>`).join('')}</div><p>Dữ liệu này đã được lưu trên thiết bị và có thể mở lại khi mạng yếu.</p></details>`}
renderStudy=function(){
 let l=chooseStudyLesson();lessonContext={title:l.question,hint:l.steps[step]};if(!lessons[level][subject]&&subject!=='Toán')subject='Toán';
 content.innerHTML=`<h1>Cùng nghĩ, cùng hiểu bài ✧</h1><p class="muted">Buddy chỉ gợi ý đúng một bước mỗi lượt để bạn tự tìm ra lời giải.</p><div class="workspace study-workspace"><div class="tabs">${['Toán','Ngữ văn','Lịch sử'].map(t=>`<button class="chip ${subject===t?'selected':''}" data-subject="${t}">${t}</button>`).join('')}</div><section class="panel lesson-card"><span class="eyebrow">BÀI MẪU · KHỐI ${grade}</span><h2>${l.question}</h2><div class="bubble lesson-hint" aria-live="polite">${l.steps[step]}</div><div class="actions"><button class="primary" id="nextStep">${step<2?'Xem gợi ý tiếp theo →':'Thử lại từ đầu ↺'}</button><button class="secondary" id="newLesson">Bài khác ↻</button><button class="secondary" id="practice">Luyện câu hỏi cùng môn</button></div></section>${renderOfflineReference()}<section class="panel buddy-chat"><div class="panel-head"><div><span class="eyebrow">SMART BUDDY BOT</span><h2>Hỏi từng bước</h2></div><span class="privacy-chip">🔒 API ở máy chủ</span></div><div class="chat-transcript" id="chatTranscript" aria-live="polite">${buddyTurns.length?buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join(''):'<div class="chat-empty">Bạn có thể gõ, đọc câu hỏi bằng giọng nói hoặc chụp đề bài.</div>'}</div><div class="notice">Buddy không đưa đáp số ngay. Mỗi lượt chỉ có một gợi ý và một câu hỏi để bạn làm tiếp.</div><label class="habit"><input id="ageConfirmed" type="checkbox"><span>Tôi từ 13 tuổi trở lên</span></label><form class="chat-composer" id="askForm"><label class="sr" for="askInput">Câu hỏi của bạn</label><textarea id="askInput" maxlength="1000" rows="3" placeholder="Ví dụ: tim x 2x+5=17 ko hieu"></textarea><div class="input-tools"><label class="input-tool" for="problemImage">▧ Chụp/tải đề<input id="problemImage" type="file" accept="image/png,image/jpeg,image/webp" capture="environment"></label><button class="input-tool" type="button" id="voiceInput" aria-pressed="false">◉ Nói câu hỏi</button><span id="inputStatus" role="status"></span><button class="primary send-ai" type="submit">Gửi cho Buddy ↗</button></div></form><div class="notice" id="askStatus" role="status">Đang kiểm tra kết nối AI…</div></section></div>`;
 document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;step=0;buddyTurns=[];render()});
 $('#nextStep').onclick=()=>{step=(step+1)%3;render()};$('#newLesson').onclick=()=>{chooseStudyLesson(true);buddyTurns=[];render()};$('#practice').onclick=()=>{question=0;score=0;answered=false;navigate('quiz')};
 $('#askForm').onsubmit=sendAIQuestion;$('#problemImage').onchange=readProblemImage;$('#voiceInput').onclick=startVoiceInput;checkAIStatus();
};
async function readProblemImage(e){const file=e.target.files?.[0],status=$('#inputStatus'),input=$('#askInput');if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5*1024*1024){status.textContent='Ảnh phải là PNG/JPG/WEBP và không quá 5 MB.';return}if(!$('#ageConfirmed').checked){status.textContent='Hãy xác nhận độ tuổi trước khi gửi ảnh.';return}status.textContent='Đang đọc chữ trong ảnh…';try{const fileData=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)});const res=await fetch('/api/tools',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ocr',grade,ageConfirmed:true,fileData,fileType:file.type}),signal:AbortSignal.timeout(60000)});const data=await res.json();if(!res.ok)throw Error(data.message||'Không đọc được ảnh.');input.value=[input.value.trim(),data.result].filter(Boolean).join('\n');status.textContent='Đã chép đề từ ảnh. Bạn hãy kiểm tra lại ký hiệu.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi khi đọc ảnh.':err.message}finally{e.target.value=''}}
function startVoiceInput(){const button=$('#voiceInput'),status=$('#inputStatus'),input=$('#askInput');if(activeRecognition){activeRecognition.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){status.textContent='Trình duyệt này chưa hỗ trợ nhập giọng nói. Bạn có thể dùng bàn phím giọng nói của điện thoại.';return}const r=new SR();activeRecognition=r;r.lang='vi-VN';r.interimResults=false;r.continuous=true;r.maxAlternatives=1;button.textContent='■ Tắt nói';button.setAttribute('aria-pressed','true');status.textContent='Đang nghe… Nhấn “Tắt nói” khi xong.';r.onresult=e=>{let text='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)text+=e.results[i][0].transcript+' ';if(text.trim())input.value=[input.value.trim(),text.trim()].filter(Boolean).join(' ')};r.onerror=e=>{if(e.error!=='aborted')status.textContent='Chưa nghe rõ. Hãy thử lại ở nơi yên tĩnh.'};r.onend=()=>{activeRecognition=null;if(button.isConnected){button.textContent='◉ Nói câu hỏi';button.setAttribute('aria-pressed','false')}if(status.textContent.startsWith('Đang nghe'))status.textContent=input.value.trim()?'Đã dừng nói và nhập nội dung.':'Đã tắt nói.'};r.start()}
sendAIQuestion=async function(e){e.preventDefault();const form=e.currentTarget,input=$('#askInput'),status=$('#askStatus'),q=input.value.trim();if(!q){status.textContent='Bạn hãy nhập câu hỏi trước nhé.';return}if(!$('#ageConfirmed').checked){status.textContent='Phần AI dành cho người từ 13 tuổi trở lên.';return}const button=form.querySelector('.send-ai');button.disabled=true;button.textContent='Đang suy nghĩ…';status.className='notice';status.textContent='Buddy đang chọn đúng một bước gợi ý…';const history=buddyTurns.slice(-8).map(x=>({role:x.role,text:x.text}));try{const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,level,grade,subject,context:lessonContext,turns:history,ageConfirmed:true}),signal:AbortSignal.timeout(85000)});let data;try{data=await r.json()}catch{throw Error('Máy chủ AI chưa trả dữ liệu hợp lệ.')}if(!r.ok)throw Error(data.message||'Máy chủ gặp lỗi.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('AI chưa trả lời. Hãy thử lại.');buddyTurns.push({role:'user',text:q},{role:'assistant',text:data.answer.trim()});buddyTurns=buddyTurns.slice(-10);input.value='';const transcript=$('#chatTranscript');transcript.innerHTML=buddyTurns.map(t=>`<div class="chat-message ${t.role}"><b>${t.role==='user'?'Bạn':'Buddy'}</b><p>${esc(t.text)}</p></div>`).join('');transcript.scrollTop=transcript.scrollHeight;status.textContent='Buddy đã gợi ý một bước. Bạn hãy thử làm rồi trả lời tiếp.'}catch(err){status.textContent=err.name==='TimeoutError'||err.name==='TypeError'?'Kết nối lỗi hoặc quá thời gian chờ. Hãy kiểm tra mạng rồi thử lại.':err.message}finally{if(button.isConnected){button.disabled=false;button.textContent='Gửi cho Buddy ↗'}}};
